parameters.jsCode:
const source = $('Edit Fields').first().json;
const rows = $input.all().map(item => item.json).filter(row =>
  row?.id != null && row.status === 'pending' && row.user_id === source.userId
);
const key = value => String(value ?? '').normalize('NFKC').trim();
const reports = Array.isArray(source.items) ? source.items : [];
const review = clarification => [{
  json: { result: 'needs_review', clarification }
}];

if (source.intent === 'add_item') {
  const plans = reports.map(item => {
    const name = key(item.itemName);
    const quantity = Number(item.quantity);
    const repeated = reports.filter(other =>
      key(other.itemName) === name
    ).length > 1;

    if (!name || repeated || !Number.isFinite(quantity) || quantity <= 0)
      return { result: 'needs_review' };

    const matches = rows.filter(row => key(row.item_name) === name);
    if (matches.length > 1)
      return { result: 'needs_review' };

    if (matches.length === 0)
      return { result: 'add_new', item };

    const row = matches[0];

    if (source.addMode !== 'increment')
      return {
        result: 'duplicate',
        itemName: name,
        quantity: row.quantity,
        unit: row.unit
      };

    if (item.unit != null && key(item.unit) !== key(row.unit))
      return { result: 'needs_review' };

    const oldQuantity = Number(row.quantity);
    if (!Number.isFinite(oldQuantity) || oldQuantity <= 0)
      return { result: 'needs_review' };

    return {
      result: 'add_increment',
      itemName: name,
      rowId: row.id,
      oldQuantity,
      newQuantity: oldQuantity + quantity,
      unit: row.unit
    };
  });

  if (!plans.length || plans.some(plan => plan.result === 'needs_review'))
    return review('商品名稱、數量或單位還不能安全確認；清單沒有更動，請一次說明一項商品。');

  const kinds = [...new Set(plans.map(plan => plan.result))];
  if (kinds.length !== 1)
    return review('這則訊息同時包含新商品與既有商品；清單沒有更動，請分成兩則訊息。');

  if (kinds[0] === 'duplicate')
    return review(
      '清單已有：' +
      plans.map(plan =>
        `${plan.itemName} ${plan.quantity}${plan.unit ?? ''}`
      ).join('、') +
      '。這次沒有重複新增；若要增加數量，請說「再加 1 瓶牛奶」，或說「牛奶改成 3 瓶」。'
    );

  return plans.map(plan => ({
    json: plan.result === 'add_new'
      ? { ...source, items: plan.item, result: 'add_new' }
      : plan
  }));
}
if (source.intent === 'bulk_update') {
  if (!['purchase_all', 'purchase_all_except'].includes(source.bulkAction)) {
    return review('這種批次操作目前還不能安全處理，清單沒有更動。');
  }

  const excludedNames = source.bulkAction === 'purchase_all_except'
    ? reports
        .filter(item => item.status === 'pending')
        .map(item => key(item.itemName))
    : [];

  if (
    source.bulkAction === 'purchase_all_except' &&
    (!excludedNames.length || excludedNames.some(name => !name))
  ) {
    return review('我還不能確認要保留哪些待買商品，清單沒有更動。');
  }

  const excludedCounts = excludedNames.map(name =>
    rows.filter(row => key(row.item_name) === name).length
  );

  if (excludedCounts.some(count => count !== 1)) {
    return review('要保留的商品無法在待買清單中唯一確認，清單沒有更動。');
  }

  const targetRows = rows.filter(row =>
    !excludedNames.includes(key(row.item_name))
  );

  if (!targetRows.length) {
    return review('沒有其他待買商品需要標記，清單沒有更動。');
  }

  const invalidQuantity = targetRows.some(row => {
    const quantity = Number(row.quantity);
    return !Number.isFinite(quantity) || quantity <= 0;
  });

  if (invalidQuantity) {
    return review('有商品數量無法確認，清單沒有更動。');
  }

  return targetRows.map(row => {
    const quantity = Number(row.quantity);

    return {
      json: {
        itemName: key(row.item_name),
        result: 'full_purchase',
        rowId: row.id,
        pendingQuantity: quantity,
        purchasedQuantity: quantity,
        remainingQuantity: 0,
        unit: row.unit
      }
    };
  });
}
const decisions = reports.map(item => {
  const name = key(item.itemName);
  const repeated = reports.filter(other =>
    key(other.itemName) === name
  ).length > 1;

  if (
    item.status !== 'purchased' &&
    source.intent !== 'partial_purchase' &&
    source.intent !== 'cancel_item' &&
    source.intent !== 'modify_item'
  )
    return { itemName: name, result: 'not_purchase' };

  if (source.intent === 'partial_purchase' && item.purchasedQuantity == null)
    return { itemName: name, result: 'quantity_needs_review' };

  if (!name || repeated)
    return { itemName: name, result: 'needs_review' };

  const matches = rows.filter(row => key(row.item_name) === name);
  if (matches.length !== 1) return {
    itemName: name,
    result: matches.length ? 'ambiguous' : 'not_found'
  };

  const row = matches[0];

if (source.intent === 'cancel_item') {
  // 沒明確說要整項取消、也沒說數量：先追問，不執行更新
  if (item.cancelAll !== true && item.quantity == null) {
    const currentQuantity = Number(row.quantity);
    const unit = row.unit ?? '';
    const currentText = Number.isFinite(currentQuantity)
      ? `${currentQuantity}${unit}`
      : `目前數量`;

    return {
      itemName: name,
      result: 'needs_review',
      clarification:
           `「${name}」${currentText}，目前清單尚未更動❕` +
  `請問要整項取消，還是只減少一些？請重新輸入完整的商品名稱與數量哦，例如：「奶粉整項取消」或「減少 1 罐奶粉」。`
    };
  }

  // 這條舊分支目前只會整項取消；指定減少數量時先擋下，避免誤刪整列
  if (item.cancelAll !== true) {
    return {
      itemName: name,
      result: 'needs_review',
      clarification:
        `收到要減少「${name}」的數量，但目前這條取消流程只支援整項取消；` +
        `清單尚未更動。`
    };
  }

  return { itemName: name, result: 'cancel_item', rowId: row.id };
}

  if (source.intent === 'modify_item') {
    const hasChange = ['quantity', 'unit', 'purpose', 'store']
      .some(field => item[field] != null);
    if (!hasChange)
      return { itemName: name, result: 'needs_review' };

    const newQuantity = item.quantity == null
      ? Number(row.quantity) : Number(item.quantity);
    if (!Number.isFinite(newQuantity) || newQuantity <= 0)
      return { itemName: name, result: 'quantity_needs_review' };

    return {
      itemName: name,
      result: 'modify_item',
      rowId: row.id,
      newQuantity,
      newUnit: item.unit ?? row.unit,
      newPurpose: item.purpose ?? row.purpose,
      newStore: item.store ?? row.store
    };
  }

  if (item.unit != null && key(item.unit) !== key(row.unit))
    return { itemName: name, result: 'unit_mismatch' };

  const pending = Number(row.quantity);
  const purchased = item.purchasedQuantity == null
    ? pending : Number(item.purchasedQuantity);

  if (
    !Number.isFinite(pending) || pending <= 0 ||
    !Number.isFinite(purchased) || purchased <= 0 || purchased > pending
  )
    return { itemName: name, result: 'quantity_needs_review' };

  return {
    itemName: name,
    result: purchased === pending ? 'full_purchase' : 'partial_purchase',
    rowId: row.id,
    pendingQuantity: pending,
    purchasedQuantity: purchased,
    remainingQuantity: pending - purchased,
    unit: row.unit
  };
});

if (
  decisions.length > 1 &&
  decisions.some(d =>
    !['full_purchase', 'partial_purchase'].includes(d.result)
  )
) {
  return review('有商品還不能安全確認，請分開回報；我尚未更動清單。');
}

return decisions.length
  ? decisions.map(decision => ({ json: decision }))
  : review('請補充要處理的商品名稱。');

parameters.jsonBody:
={{ JSON.stringify({
  replyToken: $('Edit Fields').first().json.replyToken,
  messages: [{
    type: 'text',
    text: $json.intent === 'other'
      ? (String($json.clarification ?? '').trim()
          || '這裡是家庭購物清單喔，請輸入要買的物品，或問我還有什麼沒買。')
      : $json.result === 'not_purchase'
        ? `收到，「${$json.itemName}」還沒買喔；這次沒有更動清單 🙂`
        : $json.result === 'not_found'
          ? `❗ 我還沒在待買清單找到「${$json.itemName}」，所以這次沒有更動清單喔！\n可以先問我「還有什麼沒買？」，再用清單上的完整品名回報給我 😀`
          : $json.result && !['full_purchase', 'partial_purchase'].includes($json.result)
            ? (String($json.clarification ?? '').trim()
                || `我還不能確認「${$json.itemName ?? '這項商品'}」對應哪筆待買資料，清單沒有更動喔。請補充完整品名與數量 🤗`)
            : Array.isArray($json.purchasedItems) &&
              $json.purchasedItems.length > 0 &&
              $('Edit Fields').first().json.intent === 'cancel_item'
              ? ($json.purchasedItems.some(item => item.dryRunState)
                  ? '🧪 取消測試完成，清單尚未更動。'
                  : '✅ 已取消待買\n' +
                    $json.purchasedItems
                      .filter(item => item.status === 'cancelled')
                      .map(item => `・${item.item_name} ${item.quantity}${item.unit ?? ''}`)
                      .join('\n'))
              : Array.isArray($json.purchasedItems) &&
                $json.purchasedItems.length > 0 &&
                $('Edit Fields').first().json.intent === 'modify_item'
                ? ($json.purchasedItems.some(item => item.dryRunState)
                    ? '🧪 修改測試完成，清單尚未更動。'
                    : '✅ 已修改待買\n' +
                      $json.purchasedItems
                        .map(item => `・${item.item_name} ${item.quantity}${item.unit ?? ''}`)
                        .join('\n'))
                : (() => {
    const purchasedItems = Array.isArray($json.purchasedItems)
      ? $json.purchasedItems
      : [];
    const decisions = $('Code in JavaScript').all().map(x => x.json);

    const remainingItems = $('查找待買狀態').all()
      .map(x => x.json)
      .map(row => {
        const decision = decisions.find(
          d => String(d.rowId) === String(row.id)
        );

        if (decision?.result === 'full_purchase') return null;
        if (decision?.result === 'partial_purchase') {
          return { ...row, quantity: decision.remainingQuantity };
        }
        return row;
      })
      .filter(row => row && Number(row.quantity) > 0);

    const boughtText = purchasedItems.map(item => {
      const decision = decisions.find(
       d =>
  String(d.itemName ?? '').normalize('NFKC').trim() ===
  String(item.item_name ?? '').normalize('NFKC').trim()
      );
      const remaining = Number(decision?.remainingQuantity ?? 0);
      const unit = decision?.unit ?? item.unit ?? '';

      return `・${item.item_name} ${item.quantity}${item.unit ?? ''}` +
        (decision?.result === 'partial_purchase' && remaining > 0
          ? `（還有 ${remaining}${unit}待買！）`
          : '');
    }).join('\n');

    const pendingText = remainingItems.length
      ? '🛒 目前待買清單\n' +
        remainingItems.map(item =>
          `・${item.item_name} ${item.quantity}${item.unit ?? ''}`
        ).join('\n')
      : '🎉 待買清單已買齊！';

    return `✅ 已記錄購買\n${boughtText}\n\n${pendingText}`;
  })()
  }]
}) }}

parameters.jsCode:
// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

const rows = $input.all().map(x => x.json);
const source = $('Code in JavaScript1').first().json;
const actions = Array.isArray(source.actions) ? source.actions : [];
const checked = [];
const problems = [];

const key = value =>
  String(value ?? '').normalize('NFKC').trim();

const addActions = actions.filter(a => a.action === 'add_item');
const cancelActions = actions.filter(a => a.action === 'cancel_item');

if (actions.length !== 2 || addActions.length !== 1 || cancelActions.length !== 1) {
  problems.push('目前這條路線需包含一項新增與一項取消；清單沒有更動');
}

if (problems.length === 0) {
  const add = addActions[0];
  const addName = key(add.itemName);
  const addQuantity = Number(add.quantity);

  if (!addName || !Number.isFinite(addQuantity) || addQuantity <= 0) {
    problems.push('新增商品名稱或數量不正確');
  } else {
    const matches = rows.filter(row =>
      key(row.item_name) === addName && row.status === 'pending'
    );

    if (matches.length > 1) {
      problems.push(`「${addName}」有多筆待買資料，無法安全更新`);
    } else if (
      matches.length === 1 &&
      add.unit != null &&
      matches[0].unit != null &&
      key(add.unit) !== key(matches[0].unit)
    ) {
      problems.push(`「${addName}」的單位和清單現有資料不同`);
    } else {
      const row = matches[0];
      const oldQuantity = row ? Number(row.quantity) : null;

      if (row && (!Number.isFinite(oldQuantity) || oldQuantity <= 0)) {
        problems.push(`「${addName}」目前數量不正確`);
      } else {
        checked.push({
          action: 'add_item',
          itemName: addName,
          rowId: row?.id ?? null,
          oldQuantity,
          newQuantity: row ? oldQuantity + addQuantity : addQuantity,
          unit: row?.unit ?? add.unit ?? null,
          status: row ? 'increment' : 'insert'
        });
      }
    }
  }

  const cancel = cancelActions[0];
  const cancelName = key(cancel.itemName);
  const cancelMatches = rows.filter(row =>
    key(row.item_name) === cancelName && row.status === 'pending'
  );

  if (!cancelName) {
    problems.push('取消商品名稱缺漏');
  } else if (cancelMatches.length !== 1) {
    problems.push(
      cancelMatches.length === 0
        ? `待買清單找不到「${cancelName}」`
        : `「${cancelName}」有多筆待買資料，無法安全取消`
    );
  } else {
    const row = cancelMatches[0];
    const current = Number(row.quantity);
    const requested = cancel.quantity == null ? null : Number(cancel.quantity);

    if (!Number.isFinite(current) || current <= 0) {
      problems.push(`「${cancelName}」目前數量不正確`);
    } else if (
      requested !== null &&
      (!Number.isFinite(requested) || requested <= 0 || requested > current)
    ) {
      problems.push(`「${cancelName}」要減少的數量不正確或超過目前數量`);
    } else {
      const remaining = requested === null ? 0 : current - requested;

      checked.push({
        action: 'cancel_item',
        itemName: cancelName,
        rowId: row.id,
        oldQuantity: current,
        newQuantity: requested === null ? current : remaining,
        status: remaining === 0 ? 'cancelled' : 'pending'
      });
    }
  }
}

return [{
  json: {
    intent: 'multi_action',
    userId: source.userId,
    replyToken: source.replyToken,
    valid: problems.length === 0 && checked.length === 2,
    problems,
    checked
  }
}];

const source = $('Code in JavaScript2').first().json;
const actions = source.checked || [];

const lines = actions.map(action => {
  if (action.action === 'add_item') {
    const unitText = action.unit ? ' ' + action.unit : '';
    return '・' + action.itemName + '：待買數量已更新為 ' + action.newQuantity + unitText;
  }

  if (action.action === 'cancel_item') {
    if (action.status === 'cancelled') {
      return '・' + action.itemName + '：已取消待買';
    }

    const unitText = action.unit ? ' ' + action.unit : '';
    return '・' + action.itemName + '：待買數量已更新為 ' + action.newQuantity + unitText;
  }

  return null;
}).filter(Boolean);

return [{
  json: {
    replyToken: source.replyToken,
    message: lines.length
      ? '✅ 已更新清單\n' + lines.join('\n')
      : '✅ 清單已更新'
  }
}];

const data = $input.first().json;
const reason = Array.isArray(data.problems) && data.problems.length
  ? data.problems.join('；')
  : '有商品資料無法安全確認';

const actions = $('Code in JavaScript1').first().json.actions;
const actionList = Array.isArray(actions) ? actions : [];

const isSupportedPair =
  actionList.length === 2 &&
  actionList.filter(a => a.action === 'add_item').length === 1 &&
  actionList.filter(a => a.action === 'cancel_item').length === 1;

const shouldRemindToSplit =
  actionList.length > 1 && !isSupportedPair;

return [{
  json: {
    replyToken: data.replyToken,
    message:
      `這次無法安全完成，清單沒有更動。${reason}。` +
      `請確認商品名稱或待買狀態後再試 🙂` +
      (shouldRemindToSplit ? ' 若有多項需求，請記得分開輸入哦(目前最多支援1個新增項目 搭配1個取消項目)。' : '')
  }
}];
